HERO_STR_STATIC(hero_str_735b36df, "` is not an escape here \342\200\224 `");
HERO_STR_STATIC(hero_str_3a16eda1, "` needs no escape inside ");
HERO_STR_STATIC(hero_str_556d72c0, ", write it bare");
HERO_STR_STATIC(hero_str_6830af98, "drop the backslash: `");
HERO_STR_STATIC(hero_str_4e70e704, "` is not an escape sequence \342\200\224 the escapes are ");
HERO_STR_STATIC(hero_str_67c0cce2, "; write `\\\\` for a literal backslash");
HERO_STR_STATIC(hero_str_2edf4002, "escape the backslash: `\\\\");
HERO_STR_STATIC(hero_str_3e14443c, "a carriage return written as itself inside ");
HERO_STR_STATIC(hero_str_2136798d, " \342\200\224 it is invisible on screen, so the next reader deletes it by retyping the line");
HERO_STR_STATIC(hero_str_5862de0b, "write it as `\\r`");
HERO_STR_STATIC(hero_str_7074e7b6, "this string never closes \342\200\224 strings are single-line, `\"` to `\"`");
HERO_STR_STATIC(hero_str_7caee94f, "char_literal");
HERO_STR_STATIC(hero_str_417aa306, "a character literal holds exactly one character \342\200\224 one ASCII character ('a', '0', ' ') or one escape ('\\n', '\\t') \342\200\224 `'");
