HERO_STR_STATIC(hero_str_58563470, "not a lend, a lease or a release");
HERO_STR_STATIC(hero_str_20fd5e6, "not a place");
HERO_STR_STATIC(hero_str_21560296, "extern \"s.h\"\n    function n(s: cstr) -> u64\n    function g() -> cstr\n\n");
HERO_STR_STATIC(hero_str_565b06df, "` contains itself through `");
HERO_STR_STATIC(hero_str_6063861c, "`, so it has no size");
HERO_STR_STATIC(hero_str_163ad468, "` contains itself, so it has no size");
HERO_STR_STATIC(hero_str_17e9d1c, ", then ");
HERO_STR_STATIC(hero_str_3f0ee1d7, "every value is an independent copy, so `");
